    { kind: 'car', x: 420, y: 940, angle: 0.2, speed: 380, hp: 160, w: 44, h: 22, siren: 0, bustedT: 0 },
    { kind: 'car', x: 380, y: 1060, angle: -0.2, speed: 400, hp: 160, w: 44, h: 22, siren: 0, bustedT: 0 },
